type Box = { value: i32 }
fn wrap(value: i32) -> Box {
  let b = { value };            // 式の位置: レコード(JS と同じ)
  b
}
extern "react" fn useState<T>(init: T) -> (T, (next: T) => void) = "useState";
type Curried = (a: i32) => (b: i32) => void   // 右結合、括弧は任意
fn pick(c: bool, t: Todo) -> Todo {
  if c { { ...t, done: true } } else { t }      // if の本体の波括弧は、今までどおりブロック
}
